export type Key = keyof typeof en;
type Dict = Record<Key, string>;

/** CLDR plural categories the app uses. English-like languages only need one/other; Russian adds few/many. */
export type PluralForm = "one" | "few" | "many" | "other";
/** Optional extra plural forms. A dictionary may add them for any `.one`/`.other` pair; missing ones fall back to `.other`. */
type PluralExtras = Partial<Record<`${PluralBase}.${"few" | "many"}`, string>>;

