const DICTS: Record<Lang, Dict & PluralExtras> = { en, es, pt, zh, ko, ru };

// ---------------------------------------------------------------------------
// Current language: module state plus a hook, so plain functions (notifications,
// background task) and React screens read the same value.
// ---------------------------------------------------------------------------

let current: Lang = "en";
const listeners = new Set<() => void>();

export function isLang(x: unknown): x is Lang {
  return x === "en" || x === "es" || x === "pt" || x === "zh" || x === "ko" || x === "ru";
}

export function getLanguage(): Lang {
  return current;
}

export function setLanguage(l: Lang): void {
  if (!isLang(l) || l === current) return;
  current = l;
  for (const fn of listeners) fn();
}

// "Plain words": everyday labels (src/i18nPlain.ts) on top of the dictionaries. On by default.
let plain = true;

export function getPlainWords(): boolean {
  return plain;
}

export function setPlainWords(on: boolean): void {
  if (on === plain) return;
  plain = on;
  for (const fn of listeners) fn();
}

const snapshot = () => `${current}|${plain ? 1 : 0}`;

function subscribe(fn: () => void): () => void {
  listeners.add(fn);
  return () => listeners.delete(fn);
}

/** Re-renders the calling component when the language changes. */
export function useLang(): Lang {
  useSyncExternalStore(subscribe, snapshot, snapshot); // also re-renders when plain words are switched
  return current;
}

/** Device default: Spanish, Portuguese, Chinese, Korean or Russian when the phone uses them, else English. */
export function detectLanguage(): Lang {
  let loc = "";
  try {
    loc = Intl.DateTimeFormat().resolvedOptions().locale ?? "";
  } catch {
    loc = "";
  }
  const p = loc.toLowerCase().slice(0, 2);
  return p === "es" || p === "pt" || p === "zh" || p === "ko" || p === "ru" ? p : "en";
}

export type Vars = Record<string, string | number>;

export function t(key: Key, vars?: Vars): string {
  const s = (plain ? PLAIN[current][key] : undefined) ?? DICTS[current][key] ?? en[key] ?? key;
  return vars ? s.replace(/\{(\w+)\}/g, (m, k: string) => (k in vars ? String(vars[k]) : m)) : s;
}

type PluralBase = { [K in Key]: K extends `${infer B}.one` ? B : never }[Key];

/**
 * Plural category of n in language l. Russian: 1, 21, 101 -> one; 2-4, 22-24 -> few; 0, 5-20, 25 -> many;
 * fractions -> other. Every other language: exactly 1 -> one, else other.
 */
export function pluralForm(l: Lang, n: number): PluralForm {
  if (l !== "ru") return n === 1 ? "one" : "other";
  if (!Number.isInteger(n)) return "other";
  const a = Math.abs(n);
  const d = a % 10;
  const h = a % 100;
  if (d === 1 && h !== 11) return "one";
  if (d >= 2 && d <= 4 && (h < 12 || h > 14)) return "few";
  return "many";
}

/** Picks the plural form for n (`.one`, `.few`, `.many`, else `.other`) and fills {n}. */
export function tn(base: PluralBase, n: number, vars?: Vars): string {
  const form = pluralForm(current, n);
  const key = `${base}.${form}`;
  const dict: Record<string, string | undefined> = DICTS[current];
  return t((dict[key] !== undefined ? key : `${base}.other`) as Key, { n, ...vars });
}

/** Looks up a key built at runtime, for example from an id. Falls back to `fallback` when unknown. */
export function tk(key: string, fallback: string, vars?: Vars): string {
  return key in en ? t(key as Key, vars) : fallback;
}

/** The pixel font has Latin, Latin-1 accents and Cyrillic, so only Chinese and Korean use the system font. */
export function pixelFontOk(l: Lang = current): boolean {
  return l !== "zh" && l !== "ko";
}

/** Thousands separator for the current language: 3,005, 3.005 or 3 005 (Russian, no-break space). */
export function fmtNum(v: unknown): string {
  const s = String(v ?? "");
  if (!/^\d+$/.test(s)) return s;
  return s.replace(/\B(?=(\d{3})+(?!\d))/g, current === "es" || current === "pt" ? "." : current === "ru" ? "\u00a0" : ",");
}

/** Decimal comma for Spanish, Portuguese and Russian ("33.5%" -> "33,5%"). Leaves anything else alone. */
export function fmtDec(s: string): string {
  return current === "es" || current === "pt" || current === "ru" ? s.replace(/^(\d+)\.(\d+)/, "$1,$2") : s;
}

/** Joins names with the language's list separator. */
export function joinList(items: string[]): string {
  return items.join(t("list.sep"));
}
